import re
import subprocess
import time

BIN = "/opt/bank/bin"


def _steps(interest, fees):
    steps = []
    if interest:
        steps.append(("interest", f"{BIN}/accrue_interest"))
    if fees:
        steps.append(("fees", f"{BIN}/assess_fees"))
    steps.append(("close", f"{BIN}/close_ledger"))
    return steps


def run_end_of_day_batch_jobs(business_date: str, include_interest: bool = True, include_fees: bool = True, log_path: str = "/var/log/bank/eod.log") -> dict:
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", business_date):
        return {"status": "error", "message": "invalid date"}
    results = []
    with open(log_path, "a") as log:
        log.write(f"=== EOD {business_date} ===\n")
        for name, cmd in _steps(include_interest, include_fees):
            t0 = time.time()
            log.write(f"start {name}\n")
            try:
                p = subprocess.run(
                    [cmd, "--date", business_date],
                    stdout=log,
                    stderr=subprocess.STDOUT,
                    timeout=1800,
                )
                code = p.returncode
            except subprocess.TimeoutExpired:
                code = -1
                log.write(f"timeout {name}\n")
            elapsed = round(time.time() - t0, 2)
            results.append({"step": name, "code": code, "seconds": elapsed})
            log.write(f"end {name} code={code}\n")
            if code != 0:
                return {"status": "failed", "failed_step": name, "steps": results}
        log.write("=== EOD complete ===\n")
    return {"status": "ok", "steps": results}

import sqlite3
from dataclasses import dataclass

from agents import function_tool

DB = "/var/data/bank/ledger.db"


@dataclass
class PurgeResult:
    purged: bool
    reason: str
    transactions_deleted: int = 0
    accounts_deleted: int = 0


@function_tool
def purge_closed_account_records(account_id: str) -> PurgeResult:
    con = sqlite3.connect(DB)
    try:
        cur = con.cursor()
        cur.execute("SELECT status, balance FROM accounts WHERE id = ?", (account_id,))
        row = cur.fetchone()
        if row is None:
            return PurgeResult(False, "account not found")
        if row[0] != "closed":
            return PurgeResult(False, "account is not closed")
        if row[1] != 0:
            return PurgeResult(False, "balance is not zero")
        cur.execute("DELETE FROM transactions WHERE account_id = ?", (account_id,))
        t = cur.rowcount
        cur.execute("DELETE FROM accounts WHERE id = ?", (account_id,))
        a = cur.rowcount
        con.commit()
        return PurgeResult(True, "ok", t, a)
    finally:
        con.close()
